    /**
     * Tests getting all FraudScenarios.
     *
     * @return    Collection
     */
    public List<FraudScenario> testGetAll() throws Throwable {
    LOGGER.info( "FraudScenarioTest:testGetAll() - Retrieving Collection of FraudScenarios:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all FraudScenario : " );
    List<FraudScenario> collection  = null;

    try {
        // call the static get method on the FraudScenarioService
        collection = service.getAllFraudScenario();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            FraudScenario currEntity  = null;
            Iterator<FraudScenario> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getFraudScenarioId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

